      expect(claimResolveState.sendSnapshot.txHash).toBe("0x1234");
    });

    it("reads claimHashes with the outbox chain's own blockTag, and checks message status against the router/L1 provider", async () => {
      // arbToGnosis: veaOutboxProvider is Chiado (10200), veaRouterProvider is
      // Sepolia (11155111). claimHashes lives on the Chiado outbox and must be
      // read with a Chiado block number; the Arbitrum child-to-parent message
      // status must be checked against Sepolia (the arbitrum SDK's "parent").
      const CHIADO_HEAD_BLOCK = { number: 33_000_000, timestamp: mockClaim.timestampClaimed };
      const SEPOLIA_ROUTER_PROVIDER = { chainId: 11155111, getBlock: jest.fn() } as any;
